CREATE OR REPLACE FUNCTION public.mha_admin_create_store(p_company_id bigint, p_store_code text, p_store_name text, p_public_slug text)\n RETURNS bigint\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_id bigint;\nbegin\n if auth.uid() is null or not exists(select 1 from public.mha_super_admin_identity sa join public.mha_user_profile u on u.user_id=sa.user_id where sa.user_id=auth.uid() and u.is_active and u.is_super_admin) then raise exception 'Super Admin access required' using errcode='42501';end if;\n if not exists(select 1 from public.mha_company where id=p_company_id and is_active) then raise exception 'Active company required';end if;\n if length(trim(coalesce(p_store_code,''))) not between 1 and 30 or length(trim(coalesce(p_store_name,''))) not between 2 and 150 or length(trim(coalesce(p_public_slug,''))) not between 3 and 100 or trim(p_public_slug) !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'Invalid store details or slug';end if;\n insert into public.mha_store(company_id,store_code,store_name,public_slug) values(p_company_id,trim(p_store_code),trim(p_store_name),trim(p_public_slug)) returning id into v_id;\n return v_id;\nend $function$\n

-- Explicit least-privilege grants are required on a fresh migration replay.
REVOKE ALL ON FUNCTION public.mha_admin_create_store(bigint,text,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mha_admin_create_store(bigint,text,text,text) TO authenticated;
